@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=1074  cases=33
@exercises tuning (tuning), configManager (h.cm), commandManager (h.cmgr), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-125
  @fn seedItems(h, takes, srcLen)  @ 141-146
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 148-157

# Cases
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 161-169
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 172-181
  @case 'focusState before any render returns both bits false'  [harness]  @ 184-191
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 197-210
  @case 'with no live instance, new take and unpooled duplicate mint a parked slot and select it'  [harness]  @ 214-236
  @case 'take properties renames the bound take\'s slot, not that one take'  [harness]  @ 242-260
  @case 'take properties follows the bound take when the tracker sits on another slot'  [harness]  @ 267-285
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 291-324
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 328-352
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 358-388
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 392-413
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 417-430
  @case 'the variant step rebinds the tracker to the slot stepped to and follows its placement'  [harness]  @ 436-470
  @case 'a variant step with the tracker in no instance does nothing'  [harness]  @ 474-488
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 492-515
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 522-539
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 543-566
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 570-593
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 597-632
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 636-652
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 659-686
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 690-714
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 721-742
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 748-766
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 770-788
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 792-814
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 818-842
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 848-903
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 911-940
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 946-989
  @case 'empty grid shows the single no-takes message'  [harness]  @ 995-1009
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 1016-1048
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 1052-1072

